"""Контуры: линии уровня функции двух переменных поверх заливки."""
import numpy as np


def draw(fig):
    x, y = np.meshgrid(np.linspace(-3, 3, 80), np.linspace(-2, 2, 60))
    z = (1 - x / 2 + x ** 5 + y ** 3) * np.exp(-x ** 2 - y ** 2)
    ax = fig.add_subplot()
    filled = ax.contourf(x, y, z, 12, cmap="viridis")
    ax.contour(x, y, z, 12, colors="k", linewidths=0.4)
    fig.colorbar(filled, ax=ax)
    ax.set_title("Линии уровня")


if __name__ == "__main__":
    from mpldemo import run
    run(draw)
